+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Objects;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria used when reading a page of customers.
+ *
+ * <p>Name matching deliberately lives with the backend-facing criteria, rather
+ * than in the view, so page queries and count queries always describe the same
+ * result set.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = canonicalName(name);
+        statuses = Set.copyOf(Objects.requireNonNull(statuses, "statuses"));
+    }
+
+    public static CustomerFilter unfiltered() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    /** True when this customer satisfies both the name and status criteria. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms().stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** The whitespace-normalized name used in URLs and matching. */
+    public static String canonicalName(String name) {
+        if (name == null || name.isBlank()) {
+            return "";
+        }
+        return WHITESPACE.matcher(name.trim()).replaceAll(" ");
+    }
+
+    private List<String> terms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return WHITESPACE.splitAsStream(name)
+                .map(CustomerFilter::fold)
+                .toList();
+    }
+
+    private static String fold(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
